<template>
  <div class="project-calendar">
    <header class="pc-head"><div><h2>项目日历</h2><p>{{ current.zero_date ? '正式启动 D0 · '+current.zero_date : '正式启动日待确认' }}<span v-if="current.zero_date"> · {{ current.timezone==='Asia/Shanghai'?'北京时间':current.timezone }}</span></p></div><div class="pc-actions"><DewButton v-if="writable" size="sm" @click="openZero">设置D0</DewButton><DewButton v-if="writable" size="sm" @click="openEntry()">添加关键节点</DewButton></div></header>
    <div class="pc-toolbar"><DewButton size="sm" type="ghost" @click="move(-1)">上月</DewButton><input v-model="month" type="month" aria-label="日历月份"><DewButton size="sm" type="ghost" @click="move(1)">下月</DewButton><DewButtonBar v-model="view" :items="[{value:'month',label:'月历'},{value:'timeline',label:'时间线'}]" /><DewSelect v-model="filter" :options="[{value:'all',label:'全部记录'},...Object.entries(kindText).map(([value,label])=>({value,label}))]" size="sm" /></div>
    <DewSkeleton v-if="loading" variant="rect" width="100%" height="380" />
    <div v-else-if="error" role="alert"><p>{{ error }}</p><DewButton @click="load">重试</DewButton></div>
    <template v-else>
      <p v-if="truncated" class="pc-note">记录较多，请缩小日期范围查看。</p>
      <div v-if="view==='month'" class="pc-grid"><div v-for="day in ['一','二','三','四','五','六','日']" :key="day" class="pc-week">{{ day }}</div><div v-for="cell in cells" :key="cell.date" :class="['pc-day',{'pc-outside':cell.date.slice(0,7)!==month,'pc-today':cell.date===today}]"><div class="pc-date"><span>{{ Number(cell.date.slice(8)) }}</span><small v-if="dayLabel(cell.date)">{{ dayLabel(cell.date) }}</small></div><button v-for="entry in onDate(cell.date)" :key="entry.key" :title="entry.title" :class="['pc-event',{'pc-done':entry.status==='done','pc-overdue':entry.overdue}]" @click="openEntry(entry)">{{ entry.actual_on===cell.date ? '实际 · ' : '' }}{{ entry.title }}</button></div></div>
      <div v-else class="pc-timeline"><p v-if="!visible.length" class="pc-note">此时间范围没有记录。</p><button v-for="entry in visible" :key="entry.key" class="pc-timeline-row" @click="openEntry(entry)"><span class="pc-time">{{ entry.due_on || '日期待定' }}<small v-if="numberLabel(entry.day_number)">{{ numberLabel(entry.day_number) }}</small></span><span><strong>{{ entry.title }}</strong><small>{{ kindText[entry.kind] || '记录' }} · {{ statusText[entry.status] }}<span v-if="entry.overdue"> · 已逾期</span></small><small v-if="entry.actual_on">实际 {{ entry.actual_on }}<span v-if="numberLabel(entry.actual_day_number)"> · {{ numberLabel(entry.actual_day_number) }}</span></small></span></button></div>
    </template>
    <DewDialog v-model="entryDialog" :title="form.id ? '关键节点详情' : '添加关键节点'" width="600px"><div class="pc-form"><label>标题<DewInput v-model="form.title" placeholder="例如：首版样机验证" :disabled="!canEdit" /></label><label>记录类型<DewSelect v-model="form.type" :options="Object.entries(kindText).filter(([key])=>key!=='assessment').map(([value,label])=>({value,label}))" :disabled="!!form.id || !canEdit" /></label><label>日期依据<DewSelect v-model="form.schedule_mode" :options="[{value:'absolute',label:'固定日期'},{value:'relative',label:'相对D0'}]" :disabled="!canEdit" /></label><label v-if="form.schedule_mode==='absolute'">计划日期<input v-model="form.due_on" type="date" :disabled="!canEdit" aria-label="计划日期"></label><label v-else>相对天数（启动当天为0）<DewInput v-model="form.offset_days" type="number" :disabled="!canEdit" /></label><label>说明<DewInput v-model="form.content" type="textarea" :rows="3" :disabled="!canEdit" /></label><label>状态<DewSelect v-model="form.status" :options="Object.entries(statusText).map(([value,label])=>({value,label}))" :disabled="!canEdit" /></label><label v-if="form.status==='done'">实际发生日期<input v-model="form.actual_on" type="date" :max="today" :disabled="!canEdit" aria-label="实际发生日期"></label><label v-if="canEdit">记录原因<DewInput v-model="form.reason" placeholder="说明本次新增或调整" /></label></div><template #footer><DewButton v-if="form.source==='record'||form.source==='assessment'" @click="openSource">打开原记录</DewButton><DewButton v-if="canEdit" :loading="busy" :disabled="!form.title?.trim() || !form.reason?.trim()" @click="saveEntry">保存节点</DewButton></template></DewDialog>
    <DewDialog v-model="zeroDialog" title="正式启动日 D0" width="620px"><div class="pc-form"><label>启动日期<input v-model="zeroDate" type="date" aria-label="正式启动日期"></label><label>确认或修正原因<DewInput v-model="zeroReason" placeholder="请说明启动日期的依据" /></label><DewButton :loading="busy" :disabled="!zeroDate" @click="previewZero">预览日期变化</DewButton><template v-if="preview"><p>将移动 {{ preview.changes.length }} 个未来相对计划。固定日期与已发生事实保留。</p><div v-for="change in preview.changes" :key="change.key" class="pc-preview">{{ change.title }} · {{ change.before || '待定' }} → {{ change.after }}</div></template></div><template #footer><DewButton :loading="busy" :disabled="!preview || !zeroReason.trim()" @click="saveZero">确认D0</DewButton></template></DewDialog>
  </div>
</template>
<script setup>
import {ref,reactive,computed,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {DewButton,DewButtonBar,DewInput,DewSelect,DewDialog,DewSkeleton} from '@bme/dew-ui'
import {ElMessage} from 'element-plus'
import {projectService,mutation,createRequestKey} from './service'
import {projectDayLabel as numberLabel} from './projectDayStatus'
const props=defineProps({project:Object,binding:Object,campView:Boolean}),emit=defineEmits(['changed','navigate'])
const route=useRoute(),router=useRouter(),context=ref(null)
const current=computed(()=>context.value||props.project),writable=computed(()=>current.value.can_manage&&current.value.can_write)
const today=computed(()=>new Intl.DateTimeFormat('en-CA',{timeZone:current.value.timezone||'Asia/Shanghai'}).format(new Date()))
const validMonth=value=>typeof value==='string'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(value)&&!value.startsWith('0000')
const month=ref(validMonth(route.query.month)?route.query.month:today.value.slice(0,7)),view=ref(window.matchMedia('(max-width:600px)').matches?'timeline':'month'),filter=ref('all'),entries=ref([]),loading=ref(true),error=ref(''),truncated=ref(false),busy=ref(false)
const kindText={milestone:'研发里程碑',event:'关键事件',meeting:'项目组会',record:'研发记录',outcome:'项目成果',assessment:'本期考核'},statusText={planned:'计划中',done:'已完成',cancelled:'已取消'}
const parse=s=>new Date(s+'T00:00:00Z'),iso=d=>d.toISOString().slice(0,10)
const cells=computed(()=>{const m=/^\d{4}-(0[1-9]|1[0-2])$/.test(month.value)?month.value:today.value.slice(0,7);const first=parse(m+'-01');first.setUTCDate(first.getUTCDate()-(first.getUTCDay()+6)%7);return Array.from({length:42},(_,i)=>{const d=new Date(first);d.setUTCDate(d.getUTCDate()+i);return{date:iso(d)}})})
const visible=computed(()=>entries.value.filter(e=>filter.value==='all'||e.kind===filter.value))
const range=computed(()=>({from:cells.value[0].date,to:cells.value[41].date}))
function dayLabel(date){return current.value.zero_date?numberLabel(Math.round((parse(date)-parse(current.value.zero_date))/86400000)):''}
function onDate(date){return visible.value.filter(e=>e.due_on===date||e.actual_on===date)}
function move(delta){const d=parse(month.value+'-01');d.setUTCMonth(d.getUTCMonth()+delta);month.value=iso(d).slice(0,7)}
let sequence=0
async function load(){const seq=++sequence;loading.value=true;error.value='';entries.value=[];try{const d=await projectService.calendar(props.project.id,{...range.value,binding:props.binding?.id,camp_view:props.campView?1:undefined});if(seq!==sequence)return;entries.value=d.items;truncated.value=d.truncated;context.value=props.campView?{...d.project,can_manage:false,can_write:false}:d.project;openLinked()}catch(e){if(seq===sequence)error.value=e.response?.data?.message||'日历加载失败'}finally{if(seq===sequence)loading.value=false}}
const entryDialog=ref(false),form=reactive({}),zeroDialog=ref(false),zeroDate=ref(''),zeroReason=ref(''),preview=ref(null)
const operationKey=ref(createRequestKey())
const canEdit=computed(()=>writable.value&&form.can_edit!==false)
function openEntry(entry){operationKey.value=createRequestKey();Object.assign(form,{id:null,source:'event',type:'milestone',title:'',content:'',schedule_mode:'absolute',due_on:today.value,offset_days:0,status:'planned',actual_on:today.value,reason:'',can_edit:true},entry||{});if(entry)form.type=entry.kind;entryDialog.value=true;if(entry)router.replace({query:{...route.query,entry:entry.key,month:month.value}})}
function openSource(){entryDialog.value=false;if(form.source==='assessment'){emit('navigate','delivery',form.id,{bindingId:form.binding_id,unitId:form.unit_id});return}const query={...route.query,tab:'records',record:form.id};delete query.entry;router.push({query})}
function openLinked(){const entry=entries.value.find(e=>e.key===route.query.entry);if(entry){operationKey.value=createRequestKey();Object.assign(form,{...entry,type:entry.kind,reason:''})}entryDialog.value=!!entry}
async function saveEntry(){if(busy.value)return;busy.value=true;try{const source=form.id?form.source:form.type==='milestone'?'milestone':'event';await projectService.saveEntry(props.project.id,source,{...mutation(current.value,{title:form.title,content:form.content,schedule_mode:form.schedule_mode,offset_days:Number(form.offset_days),due_on:form.due_on||null,status:form.status,actual_on:form.status==='done'?form.actual_on:null,kind:form.type==='milestone'?'event':form.type,reason:form.reason}),idempotency_key:operationKey.value},form.id);entryDialog.value=false;const query={...route.query};delete query.entry;await router.replace({query});await load();emit('changed');ElMessage.success('节点已保存')}catch(e){ElMessage.error(e.response?.data?.message||'保存失败')}finally{busy.value=false}}
function openZero(){zeroDate.value=current.value.zero_date||today.value;zeroReason.value='';preview.value=null;zeroDialog.value=true}
async function previewZero(){busy.value=true;try{preview.value=await projectService.previewZero(props.project.id,zeroDate.value)}catch(e){ElMessage.error(e.response?.data?.message||'预览失败')}finally{busy.value=false}}
async function saveZero(){if(busy.value||!preview.value)return;busy.value=true;try{await projectService.changeZero(props.project.id,{...mutation(current.value,{zero_date:zeroDate.value,reason:zeroReason.value,confirm:true}),expected_version:preview.value.project_version});zeroDialog.value=false;await load();emit('changed');ElMessage.success('正式启动日已确认')}catch(e){ElMessage.error(e.response?.data?.message||'更新失败')}finally{busy.value=false}}
watch(zeroDate,()=>preview.value=null)
watch(month,value=>{if(validMonth(value)&&route.query.month!==value){const query={...route.query,month:value};delete query.entry;router.push({query})}})
watch(()=>route.query.month,value=>{if(validMonth(value))month.value=value})
watch(()=>[props.project.id,props.binding?.id,props.campView,month.value],()=>{context.value=null;entryDialog.value=zeroDialog.value=false;load()},{immediate:true})
watch(()=>route.query.entry,openLinked);onBeforeUnmount(()=>sequence++)
</script>
<style scoped>
.pc-head,.pc-actions,.pc-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.pc-head{justify-content:space-between;margin-bottom:20px}.pc-head h2{margin:0}.pc-head p,.pc-note{font-size:13px;color:var(--dew-text-muted)}.pc-toolbar{margin-bottom:20px}.pc-toolbar :deep(.dew-select){width:150px}.pc-toolbar input,.pc-form input{border:1px solid var(--dew-card-flat-border);border-radius:8px;padding:8px 10px;color:var(--dew-text);background:var(--dew-card-flat-bg);font:inherit;max-width:100%}.pc-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));border-left:1px solid var(--dew-card-flat-border);border-top:1px solid var(--dew-card-flat-border)}.pc-week{text-align:center;font-size:12px;padding:8px}.pc-day{min-height:115px;padding:7px;border-right:1px solid var(--dew-card-flat-border);border-bottom:1px solid var(--dew-card-flat-border);min-width:0}.pc-date{display:flex;justify-content:space-between;gap:3px;flex-wrap:wrap;font-size:13px;margin-bottom:7px}.pc-date small{font-size:10px;color:var(--dew-text-muted)}.pc-outside{opacity:.5}.pc-today .pc-date{color:var(--color-primary);font-weight:600}.pc-event{display:block;width:100%;padding:5px;margin:4px 0;background:var(--color-primary-light);color:var(--color-primary);border:0;border-radius:5px;text-align:left;font-size:11px;overflow-wrap:anywhere;cursor:pointer}.pc-done{color:var(--dew-text-muted)}.pc-overdue{border-left:2px solid var(--color-danger)}.pc-timeline-row{display:flex;gap:25px;width:100%;padding:18px 0;text-align:left;background:transparent;border:0;border-bottom:1px solid var(--dew-card-flat-border);color:var(--dew-text);font:inherit;cursor:pointer}.pc-time{min-width:100px;flex-shrink:0}.pc-timeline-row>span:last-child{min-width:0;overflow-wrap:anywhere}.pc-timeline-row small{display:block;color:var(--dew-text-muted);font-size:12px;line-height:1.8}.pc-form{display:flex;flex-direction:column;gap:16px}.pc-form label{display:flex;flex-direction:column;gap:7px;font-size:13px}.pc-preview{font-size:12px;border-top:1px solid var(--dew-card-flat-border);padding-top:8px}@media(max-width:600px){.pc-day{padding:4px;min-height:85px}.pc-event{font-size:10px;padding:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pc-timeline-row{gap:14px}.pc-date small{font-size:9px}}
</style>
